    /// <summary>
    /// control method for METPaymReconDueDate button
    /// </summary>
    /// <param name = "sender">Form</param>
    /// <param name = "e">form arguments</param>
    [
        FormControlEventHandler(formControlStr(LedgerJournalTransVendPaym, METPaymReconDueDate), FormControlEventType::Clicked),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface'),
        SuppressBPWarningAttribute('BPUpgradeCodeLateBoundCall', 'Standard call')
    ]
    public static void METPaymReconDueDate_OnClicked(FormControl sender, FormControlEventArgs e)
    {
        FormRun             formRun                 = sender.formRun();
        FormDataSource      ledgerJournalTrans_DS   = formRun.dataSource(tableStr(LedgerJournalTrans));

        LedgerJournalTrans currentRecord = ledgerJournalTrans_DS.cursor();

        ledgerJournalTrans_DS.positionToRecord(currentRecord);
        ledgerJournalTrans_DS.executeQuery();
    }

/// <summary>
/// control method for buttonPaymReconciliation button
/// </summary>
/// <param name="sender">form</param>
/// <param name="e">arguments</param>
[FormControlEventHandler(formControlStr(LedgerJournalTransVendPaym, buttonPaymReconciliation), FormControlEventType::Clicked),
    SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface'),
    SuppressBPWarningAttribute('BPUpgradeCodeLateBoundCall', 'Standard call')]
public static void buttonPaymReconciliation_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun             formRun                 = sender.formRun();
    formRun.metEnableButtonsActive();
}

